out=[row[10:23].copy() for row in grid]
panel_specs=[(1,11,5,13,5),(1,17,7,9,1),(7,11,6,1,1),(7,17,9,5,5),(13,11,4,13,1),(13,17,2,1,5)]
# Each tuple: panel top-left row/col, tile color, source 3x3 top-left row/col
for pr,pc,col,sr,sc in panel_specs:
    # make the 5x5 panel, including its solid border
    for dr in range(5):
        for dc in range(5):
            out[pr+dr][pc-10+dc]=col
    for dr in range(1,4):
        for dc in range(1,4):
            out[pr+dr][pc-10+dc] = 3 if grid[sr+dr-1][sc+dc-1]==col else col
for i,r in enumerate(out): print(i,' '.join(map(str,r)))
